  q('「まさか」と呼応する表現として最も適切なものはどれか。', ['〜ないだろう', '〜ください', '〜ようだ', '〜ても', '〜か'], '「まさか〜ないだろう(まい)」と打ち消し推量で受ける。');

  c('語句の意味');
  q('「やおら」の本来の意味はどれか。', ['ゆっくりと、静かに', '急に、いきなり', '力強く', 'やっとのことで', 'こっそりと'], '「やおら」は落ち着いてゆっくり動作を始めるさま。「急に」は誤用。');
  q('「憮然」の本来の意味はどれか。', ['失望してぼんやりするさま', '腹を立てているさま', '平然としているさま', '得意になっているさま', '驚いて声も出ないさま'], '「憮然(ぶぜん)」は失望・落胆してどうすることもできないさま。「腹を立てる」は本来の意味ではない。');
  q('「破天荒」の本来の意味はどれか。', ['今まで誰もしなかったことを成し遂げること', '豪快で大胆なようす', '乱暴で手がつけられないこと', '天気が大荒れになること', '計画がすっかり駄目になること'], '「天荒」は未開の荒れ地。それを破ることから、前人未到のことを成し遂げる意。');
  q('「確信犯」の本来の意味はどれか。', ['政治的・宗教的などの信念に基づき、正しいと信じてなされる犯罪', '悪いことだとわかっていながらなされる犯罪', '証拠がそろっていて疑いのない犯罪', '何度も繰り返される犯罪', '計画的に準備された犯罪'], '本来は、自分の信念から正しいと確信して行う犯罪のこと。');
  q('「うがった見方をする」の本来の意味はどれか。', ['物事の本質を的確に捉えた見方をする', '疑ってかかるような見方をする', 'ひねくれた見方をする', '一方的に決めつけた見方をする', '表面だけを見た浅い見方をする'], '「穿(うが)つ」は穴をあける意から、物事を深く掘り下げ本質を捉えること。');
  q('「世間ずれ」の本来の意味はどれか。', ['世間で苦労して、ずる賢くなっていること', '世の中の考えから外れていること', '世間のことをよく知らないこと', '流行に敏感なこと', '人付き合いが苦手なこと'], '「世間擦れ」と書く。世間でもまれて悪賢くなること。「ずれている」意ではない。');
  q('「雨模様」の本来の意味はどれか。', ['雨が降りそうなようす', '小雨が降ったりやんだりしているようす', '雨が激しく降っているようす', '雨上がりのようす', '雨の日が続くようす'], '本来は、今にも雨が降りそうな空のようす。');
  q('「御の字」の本来の意味はどれか。', ['大いにありがたいこと', '一応は納得できること', '最低限の水準であること', '相手に敬意を示すこと', '形だけ整っていること'], '「御」の字をつけたいほどありがたい、という意味。「まあまあ」ではなく「十分満足」。');

