  q('『金閣寺』の作者はだれか。', ['三島由紀夫', '川端康成', '水上勉', '井上靖', '安部公房'], '三島由紀夫の作品は他に『仮面の告白』『潮騒』『豊饒の海』など。');
  q('『細雪』の作者はだれか。', ['谷崎潤一郎', '永井荷風', '志賀直哉', '川端康成', '有島武郎'], '谷崎潤一郎の作品は他に『刺青』『痴人の愛』『春琴抄』など。');
  q('『暗夜行路』の作者はだれか。', ['志賀直哉', '武者小路実篤', '有島武郎', '夏目漱石', '島崎藤村'], '志賀直哉は白樺派の作家。他に『城の崎にて』『小僧の神様』。');
  q('『破戒』の作者はだれか。', ['島崎藤村', '田山花袋', '国木田独歩', '徳田秋声', '正宗白鳥'], '島崎藤村の自然主義文学の代表作。他に『夜明け前』、詩集『若菜集』。田山花袋は『蒲団』。');
  q('『たけくらべ』の作者はだれか。', ['樋口一葉', '与謝野晶子', '平塚らいてう', '林芙美子', '宮本百合子'], '樋口一葉の作品は他に『にごりえ』『十三夜』。');
  q('『蟹工船』の作者はだれか。', ['小林多喜二', '葉山嘉樹', '徳永直', '横光利一', '井伏鱒二'], 'プロレタリア文学の代表作。');
  q('『山月記』の作者はだれか。', ['中島敦', '芥川龍之介', '梶井基次郎', '太宰治', '堀辰雄'], '中島敦の作品は他に『李陵』『名人伝』。');
  q('言文一致体で書かれた小説『浮雲』の作者はだれか。', ['二葉亭四迷', '坪内逍遥', '尾崎紅葉', '幸田露伴', '山田美妙'], '二葉亭四迷『浮雲』は日本の近代小説の先駆け。坪内逍遥は評論『小説神髄』。');
  q('『曽根崎心中』の作者はだれか。', ['近松門左衛門', '井原西鶴', '竹田出雲', '鶴屋南北', '河竹黙阿弥'], '近松門左衛門は元禄期の人形浄瑠璃・歌舞伎の作者。井原西鶴は浮世草子『好色一代男』『日本永代蔵』。');
  q('『南総里見八犬伝』の作者はだれか。', ['曲亭馬琴', '十返舎一九', '式亭三馬', '上田秋成', '山東京伝'], '曲亭(滝沢)馬琴の読本。十返舎一九は『東海道中膝栗毛』、式亭三馬は『浮世風呂』、上田秋成は『雨月物語』。');
  q('歌集『一握の砂』の作者はだれか。', ['石川啄木', '与謝野晶子', '正岡子規', '斎藤茂吉', '北原白秋'], '石川啄木の歌集は『一握の砂』『悲しき玩具』。与謝野晶子は『みだれ髪』、斎藤茂吉は『赤光』。');

