  q('"conceal" と最も意味が近い語はどれか。', ['hide', 'reveal', 'cancel', 'consult', 'conclude'], 'conceal = hide(隠す)。反意語は reveal。');
  q('"inevitable" と最も意味が近い語はどれか。', ['unavoidable', 'invisible', 'incredible', 'uncertain', 'unexpected'], 'inevitable = unavoidable(避けられない)。');
  q('"diminish" と最も意味が近い語はどれか。', ['decrease', 'finish', 'dismiss', 'expand', 'distinguish'], 'diminish = decrease, reduce(減少する、減らす)。');
