  q('ブラジルの首都はどこか。', ['ブラジリア', 'リオデジャネイロ', 'サンパウロ', 'サルバドール', 'ブエノスアイレス'], '1960年にリオデジャネイロから内陸の計画都市ブラジリアに移された。');
